<?php
declare(strict_types=1);
require_once __DIR__.'/../api/v1/domains.php';
require_once __DIR__.'/../api/v1/online.php';
$checks=0;$check=static function(bool $value,string $message)use(&$checks){if(!$value)throw new RuntimeException($message);$checks++;};
$abilityId='ability-93fa3849-3fbf-43fa-84cb-0c0c9d7f4189';
$source=['id'=>'source','x'=>20,'y'=>50,'size'=>40,'layerId'=>'ground','followCharacter'=>false];
$target=['id'=>'target','x'=>70,'y'=>60,'size'=>90,'layerId'=>'ground','followCharacter'=>false];
$map=['background'=>'/fake.webp','activeLayerId'=>'ground','naturalWidth'=>1000,'naturalHeight'=>600,'gridSize'=>50,'tokens'=>[$source,$target]];
$application=['abilityId'=>$abilityId,'dotId'=>'real-dot','effectId'=>'buff','sourceTokenId'=>'source','targetTokenId'=>'target'];
$attack=['id'=>'attack','attackId'=>'halberd','status'=>'applied','sceneId'=>'scene','layerId'=>'ground','sourceTokenId'=>'source','targetTokenId'=>'target','hit'=>['outcome'=>['success'=>true]],'poisonApplications'=>[$application]];
$activation=applicationTrustedSpellVisual(['id'=>$abilityId],['sceneId'=>'scene','source'=>$source,'map'=>$map]);
$check($activation['presetId']==='venom-awakening'&&$activation['anchorTokenId']==='source','Activation sur le lanceur effectif');
$effects=applicationTrustedPoisonImpactVisuals($attack,['map'=>$map]);$spell=$effects[0]['spell'];
$check($spell['presetId']==='venom-ramifications'&&$spell['anchorTokenId']==='target','Impact sur la victime');
$check($spell['targetPoint']===['x'=>70,'y'=>60]&&$spell['source']===['x'=>20,'y'=>50,'size'=>40],'Direction réelle conservée');
$check(applicationTrustedPoisonImpactVisuals([...$attack,'poisonApplications'=>[]],['map'=>$map])===[],'Aucune charge réelle, aucun impact');
$check(applicationTrustedPoisonImpactVisuals([...$attack,'status'=>'pending'],['map'=>$map])===[],'Aucun impact anticipé');
$check(applicationTrustedPoisonImpactVisuals([...$attack,'hit'=>['outcome'=>['success'=>false]]],['map'=>$map])===[],'Aucun impact sur un échec');
$check(applicationTrustedPoisonImpactVisuals([...$attack,'poisonApplications'=>[[...$application,'targetTokenId'=>'other']]],['map'=>$map])===[],'La référence de cible doit correspondre');
$check(count(applicationTrustedPoisonImpactVisuals([...$attack,'poisonApplications'=>[$application,[...$application,'dotId'=>'other-dot']]],['map'=>$map]))===1,'Les charges simultanées ne superposent pas le dessin');
$periodic=applicationTrustedEnhancementSpellVisual(['sourceAbilityId'=>$abilityId],['phase'=>'periodic','map'=>$map,'sceneId'=>'scene','targetPoint'=>$target]);
$check($periodic['presetId']==='venom-affliction'&&$periodic['source']===['x'=>70,'y'=>60,'size'=>90],'Le tick suit la victime sans dévoiler le lanceur');
$check(applicationTrustedEnhancementSpellVisual(['sourceAbilityId'=>'unknown'],['phase'=>'periodic','map'=>$map,'sceneId'=>'scene','targetPoint'=>$target])===null,'Aucune liaison inventée');
$public=['sceneId'=>'scene','layerId'=>'ground','sourceTokenId'=>'target','visibleTokenIds'=>['target'],'visible'=>static fn()=>true];
$check(applicationPublicSpellVisual($periodic,$public)!==null,'Pulsation visible sur cible visible');
$check(applicationPublicSpellVisual($periodic,[...$public,'visibleTokenIds'=>[]])===null,'Aucune fuite du pion caché');
$activity=[];$cue=normalizeApplicationAbilityCompletionCue(['spell'=>$periodic]);
appendApplicationAbilityCueEvent($activity,$cue,'scene','ground','target','public','cue-fixed');
appendApplicationAbilityCueEvent($activity,$cue,'scene','ground','target','public','cue-fixed');
$check(count($activity['abilityCueEvents'])===1,'Le même reçu ne rejoue pas la pulsation');
$state=['activeSceneId'=>'scene','map'=>$map,'attackEnhancements'=>[],'damageOverTime'=>[['id'=>'dot-a','sceneId'=>'scene','targetTokenId'=>'target','family'=>'poison','remainingTurns'=>2],['id'=>'dot-b','sceneId'=>'scene','targetTokenId'=>'target','family'=>'poison','remainingTurns'=>5]]];
$skin=applicationTokenBuffVisuals($target,$state,'scene');
$check(count($skin)===1&&$skin[0]['skin']==='venom-target'&&$skin[0]['remainingTurns']===5,'Un film unique pour les charges actives');
$check(applicationTokenBuffVisuals([...$target,'dimSilhouette'=>true],$state,'scene')===[],'Aucune peau sur silhouette');
$check(applicationTokenBuffVisuals([...$target,'id'=>'clone'],$state,'scene')===[],'Le clone reste indépendant');
$state['damageOverTime']=[];$check(applicationTokenBuffVisuals($target,$state,'scene')===[],'Retrait dès la dernière charge');
$state['attackEnhancements']=[['id'=>'buff','holder'=>'token:source','targetTokenId'=>'source','casterTokenId'=>'source','abilityId'=>$abilityId,'sceneId'=>'scene','mode'=>'on-attack-dot','turns'=>5,'remainingTurns'=>5,'dot'=>['label'=>'Poison mortel','formula'=>'1d20','turns'=>5]]];
$buff=applicationTokenBuffVisuals($source,$state,'scene');$check(($buff[0]['skin']??'')==='venom-source','Ancien buff actif identifié sans réécrire ses ressources');
echo json_encode(['ok'=>true,'checks'=>$checks],JSON_THROW_ON_ERROR);
